package com.indice.erp.files;
import com.indice.erp.auth.*;
import com.indice.erp.billing.subscription.*;
import com.indice.erp.billing.storage.CompanyStorageMeter;
import com.indice.erp.storage.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;
import java.io.*;
import static com.indice.erp.files.FileContracts.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"app.email.enabled=false","app.mail-accounts.worker-enabled=false","app.mailing.worker-enabled=false"})
@AutoConfigureMockMvc
@Transactional
class FileLibraryIntegrationTest {
 @Autowired JdbcTemplate db;@Autowired FileLibraryService service;@Autowired FileUploadService uploads;@Autowired MockMvc mvc;@Autowired ObjectMapper mapper;
 @MockitoBean ObjectStorageService storage;@MockitoBean CompanyStorageMeter meter;@MockitoBean CompanySubscriptionService subscription;
 long company,other,owner,reader,outsider;AuthSessionUser a,b,x;
 long insert(String sql,Object...args){var key=new GeneratedKeyHolder();db.update(c->{var st=c.prepareStatement(sql,java.sql.Statement.RETURN_GENERATED_KEYS);for(int i=0;i<args.length;i++)st.setObject(i+1,args[i]);return st;},key);return key.getKey().longValue();}
 long member(long company,String name){long id=insert("INSERT INTO users(email,password_hash,full_name) VALUES(?,'synthetic-only',?)",UUID.randomUUID()+"@example.com",name);insert("INSERT INTO user_companies(user_id,company_id,role,status) VALUES(?,?,'user','active')",id,company);return id;}
 @BeforeEach void setup(){assertThat(db.queryForObject("SELECT DATABASE()",String.class)).isEqualTo("indice_test_db");company=insert("INSERT INTO companies(name) VALUES('Files synthetic')");other=insert("INSERT INTO companies(name) VALUES('Other synthetic')");owner=member(company,"Owner synthetic");reader=member(company,"Reader synthetic");outsider=member(other,"Outsider synthetic");a=new AuthSessionUser(owner,company,"Owner synthetic","user");b=new AuthSessionUser(reader,company,"Reader synthetic","user");x=new AuthSessionUser(outsider,other,"Outsider synthetic","user");when(subscription.currentStatus(anyLong())).thenReturn(CompanySubscriptionStatus.activeLegacy());}
 String key(AuthSessionUser actor){return FileAccess.key(actor);}String uuid(){return UUID.randomUUID().toString();}
 Entry folder(AuthSessionUser actor,String parent,String name){return service.folder(actor,key(actor),uuid(),new Folder(name,parent));}
 Sharing share(AuthSessionUser actor,Entry entry,long recipient,int permission){return service.share(actor,key(actor),entry.id(),new Share(entry.version(),uuid(),List.of(new GrantInput(recipient,permission))));}
 Entry change(AuthSessionUser actor,Entry entry,String action,String parent){return service.change(actor,key(actor),entry.id(),new Change(entry.version(),uuid(),action,entry.name(),parent));}
 MockHttpSession session(AuthSessionUser actor){var session=new MockHttpSession();session.setAttribute(SessionAuthService.SESSION_USER_ID,actor.userId());session.setAttribute(SessionAuthService.SESSION_COMPANY_ID,actor.companyId());session.setAttribute(SessionAuthService.SESSION_USER_NAME,actor.userName());session.setAttribute(SessionAuthService.SESSION_LOGIN_CSRF,"synthetic-csrf");return session;}
 @Test void privateFoldersAreScopedAndOnlyActiveInternalMembersCanReceiveAccess(){var entry=folder(a,null,"Private");assertThat(service.list(b,null,"OWNED","",1,25,"ALL").items()).isEmpty();assertThatThrownBy(()->service.get(b,entry.id())).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->service.get(x,entry.id())).isInstanceOf(ResponseStatusException.class);assertThat(service.members(a)).extracting(Member::id).containsExactly(owner,reader);assertThatThrownBy(()->share(a,entry,outsider,1)).isInstanceOf(ResponseStatusException.class);share(a,entry,reader,1);assertThat(service.get(b,entry.id()).permission()).isEqualTo(1);}
 @Test void folderAccessIsInheritedAndRevocationImmediatelyRemovesDescendantAccess(){var parent=folder(a,null,"Parent");var child=folder(a,parent.id(),"Child");var shared=share(a,parent,reader,1);assertThat(service.get(b,child.id()).permission()).isEqualTo(1);assertThat(service.sharing(b,child.id()).grants()).anyMatch(g->g.inherited()&&g.userId()==reader);service.share(a,key(a),parent.id(),new Share(shared.entry().version(),uuid(),List.of()));assertThatThrownBy(()->service.get(b,child.id())).isInstanceOf(ResponseStatusException.class);assertThat(service.list(b,null,"SHARED","Child",1,25,"ALL").items()).isEmpty();}
 @Test void collaboratorsCanAddAndRenameButCannotChangeSharingOrTrashOthersFiles(){var parent=folder(a,null,"Team");var granted=share(a,parent,reader,2);var own=folder(b,parent.id(),"Added by collaborator");assertThat(own.permission()).isEqualTo(3);var renamed=service.change(b,key(b),parent.id(),new Change(granted.entry().version(),uuid(),"RENAME","Team renamed",null));assertThat(renamed.name()).isEqualTo("Team renamed");assertThatThrownBy(()->share(b,renamed,owner,3)).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->change(b,renamed,"TRASH",null)).isInstanceOf(ResponseStatusException.class);}
 @Test void staleChangesAndChangedRetriesDoNotOverwriteAndFolderCreationIsIdempotent(){String id=uuid();var created=service.folder(a,key(a),id,new Folder("Original",null));assertThat(service.folder(a,key(a),id,new Folder("Original",null)).version()).isEqualTo(1);String mutation=uuid();var input=new Change(1,mutation,"RENAME","Latest",null);var renamed=service.change(a,key(a),id,input);assertThat(service.change(a,key(a),id,input).version()).isEqualTo(2);assertThatThrownBy(()->service.change(a,key(a),id,new Change(1,mutation,"RENAME","Wrong",null))).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->change(a,created,"TRASH",null)).isInstanceOf(ResponseStatusException.class);assertThat(service.get(a,id).name()).isEqualTo(renamed.name());}
 @Test void movingIntoDescendantsFailsWithoutChangingParents(){var parent=folder(a,null,"Parent");var child=folder(a,parent.id(),"Child");assertThatThrownBy(()->change(a,parent,"MOVE",child.id())).isInstanceOf(ResponseStatusException.class);assertThat(service.get(a,parent.id()).parentId()).isNull();assertThat(service.destinations(a,parent.id())).isEmpty();}
 @Test void trashHidesDescendantsAndRestoreRetainsFilesAndPermissions(){var parent=folder(a,null,"Parent");var child=folder(a,parent.id(),"Child");var grant=share(a,parent,reader,1);var trashed=change(a,grant.entry(),"TRASH",null);assertThatThrownBy(()->service.get(b,child.id())).isInstanceOf(ResponseStatusException.class);assertThat(service.list(a,null,"TRASH","",1,25,"ALL").items()).extracting(Entry::id).containsExactly(parent.id());change(a,trashed,"RESTORE",null);assertThat(service.get(b,child.id()).permission()).isEqualTo(1);assertThat(db.queryForObject("SELECT COUNT(*) FROM file_library_entries WHERE company_id=?",Long.class,company)).isEqualTo(2);}
 @Test void searchHonorsFolderAndScopeAndDoesNotRevealHiddenAncestorNames(){var hidden=folder(a,null,"Hidden ancestor");var child=folder(a,hidden.id(),"Selected document");share(a,child,reader,1);var page=service.list(b,child.id(),"SHARED","",1,25,"ALL");assertThat(page.breadcrumbs()).extracting(Crumb::name).containsExactly("Selected document");assertThat(service.get(b,child.id()).parentId()).isNull();assertThat(service.list(b,null,"OWNED","Selected",1,25,"ALL").items()).isEmpty();assertThat(service.list(b,null,"SHARED","Selected",1,25,"ALL").items()).hasSize(1);}
 @Test void nativeHttpRequiresSessionCsrfAndActorAndInactiveMembersLoseAccess()throws Exception{mvc.perform(get("/api/v1/files")).andExpect(status().isUnauthorized());String id=uuid(),body=mapper.writeValueAsString(new Folder("New",null));mvc.perform(put("/api/v1/files/folders/"+id).session(session(a)).header("X-Files-Actor",key(a)).contentType("application/json").content(body)).andExpect(status().isForbidden());mvc.perform(put("/api/v1/files/folders/"+id).session(session(a)).header("X-CSRF-Token","synthetic-csrf").header("X-Files-Actor","another-company").contentType("application/json").content(body)).andExpect(status().isConflict());mvc.perform(put("/api/v1/files/folders/"+id).session(session(a)).header("X-CSRF-Token","synthetic-csrf").header("X-Files-Actor",key(a)).contentType("application/json").content(body)).andExpect(status().isOk());mvc.perform(get("/api/v1/files").session(session(a))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));db.update("UPDATE user_companies SET status='inactive' WHERE company_id=? AND user_id=?",company,owner);assertThatThrownBy(()->service.get(a,id)).isInstanceOf(ResponseStatusException.class);}
 @Test void uploadUsesExistingCapacitySealsAndRetriesWithoutReplacingReadyContent(){when(storage.isEnabled()).thenReturn(true);when(meter.presignExistingCapacity(anyLong(),anyString(),anyString(),anyString(),anyString(),anyLong(),anyInt())).thenReturn(new PresignedUpload("private","http://127.0.0.1/upload",java.time.Instant.now(),Map.of("Content-Type","text/plain")));String id=uuid();var input=new UploadInput("Notes.txt",null,5);uploads.prepare(a,key(a),id,input);when(storage.objectExists(anyString(),anyString())).thenReturn(true);when(storage.objectMetadata(anyString(),anyString())).thenReturn(new StoredObjectMetadata(5,"text/plain"));when(storage.readObjectPrefix(anyString(),anyString(),anyInt())).thenReturn("hello".getBytes());var registered=uploads.register(a,key(a),id);assertThat(registered.name()).isEqualTo("Notes.txt");assertThat(uploads.register(a,key(a),id)).isEqualTo(registered);assertThat(uploads.prepare(a,key(a),id,input).ready()).isEqualTo(registered);verify(storage,times(1)).copyObject(anyString(),contains("/staging/"),contains("/assets/"));verify(meter,times(1)).commitExistingCapacity(eq(company),anyString(),anyString(),anyString(),eq(5L));assertThatThrownBy(()->uploads.content(b,id)).isInstanceOf(ResponseStatusException.class);}
 @Test void invalidMediaNeverRegistersOrCommitsQuota(){when(storage.isEnabled()).thenReturn(true);when(meter.presignExistingCapacity(anyLong(),anyString(),anyString(),anyString(),anyString(),anyLong(),anyInt())).thenReturn(new PresignedUpload("private","http://127.0.0.1/upload",java.time.Instant.now(),Map.of()));String id=uuid();uploads.prepare(a,key(a),id,new UploadInput("Photo.png",null,5));when(storage.objectExists(anyString(),anyString())).thenReturn(true);when(storage.objectMetadata(anyString(),anyString())).thenReturn(new StoredObjectMetadata(5,"image/png"));when(storage.readObjectPrefix(anyString(),anyString(),anyInt())).thenReturn("wrong".getBytes());assertThatThrownBy(()->uploads.register(a,key(a),id)).isInstanceOf(ResponseStatusException.class);assertThat(db.queryForObject("SELECT status FROM file_library_entries WHERE company_id=? AND id=?",String.class,company,id)).isEqualTo("PENDING");verify(meter,never()).commitExistingCapacity(anyLong(),anyString(),anyString(),anyString(),anyLong());}
 @Test void subscriptionLockAndForbiddenNamesDoNotCreateEntries(){when(subscription.currentStatus(company)).thenReturn(CompanySubscriptionStatus.blocked("unavailable"));assertThatThrownBy(()->folder(a,null,"Blocked")).isInstanceOf(ResponseStatusException.class);when(subscription.currentStatus(company)).thenReturn(CompanySubscriptionStatus.activeLegacy());assertThatThrownBy(()->folder(a,null,"../Wrong")).isInstanceOf(ResponseStatusException.class);assertThat(db.queryForObject("SELECT COUNT(*) FROM file_library_entries WHERE company_id=?",Long.class,company)).isZero();}
 @Test void quotaErrorsAreActionableWithoutCreatingAnEntry()throws Exception{when(storage.isEnabled()).thenReturn(true);when(meter.presignExistingCapacity(anyLong(),anyString(),anyString(),anyString(),anyString(),anyLong(),anyInt())).thenThrow(new IllegalStateException("Existing storage capacity is insufficient"));mvc.perform(post("/api/v1/files/uploads/"+uuid()).session(session(a)).header("X-CSRF-Token","synthetic-csrf").header("X-Files-Actor",key(a)).contentType("application/json").content(mapper.writeValueAsString(new UploadInput("Notes.txt",null,5)))).andExpect(status().isUnprocessableEntity()).andExpect(jsonPath("$.code").value("files_storage_capacity"));}
}
